function out = k_continuations(data, opts)
%K_CONTINUATIONS builds a small report from data
%   The continuation lines are deliberately messy: commas and operators
%   at the start of lines, comments after the continuation marker.

if nargin < 2, opts = struct(); end

labels = {'alpha', ...   % first label
          'beta',  ...   % second label
          'gamma'};
vals = [ 1.5, 2.25, ...
         3.75, 4.0 ...   % trailing comment
       ];

total = sum(vals) + ...
        mean(vals) - ...
        std(vals);

msg = ['this message is ' ...
       'split across ' ...
       'several strings'];

out = struct( ...
    'labels', {labels} ...
  , 'values', vals ...
  , 'total', total ...
  , 'message', msg ...
  );

result = table( ...
    labels(:) ...
    , vals(1:3).' ...
    , 'VariableNames', {'Name', 'Value'} ...
    );
out.table = result;

if total > 0 && ...
        numel(vals) > 2 || ...
        isfield(opts, 'force')
    out.flag = true;
else
    out.flag = false;
end

fprintf('%s %d\n', ...
    'count', ...
    numel(vals));

s = sprintf(['%s: %.2f ' ...
    '%s'], 'x', ...
    total, 'y');
out.text = s;

% long matrix literal, one row per line, with the semicolons at the start
M = [ 1 2 3 ...
    ; 4 5 6 ...
    ; 7 8 9 ];
out.M = M;

% long condition written as a list of checks
ok = isnumeric(vals) ...
    & all(vals > 0) ...
    & numel(labels) == numel(vals(1:3)) ...
    | false;
out.ok = ok;

% argument list with a cell wrapped across lines
c = cellfun(@(x, y) ...
    x + y, ...
    {1, 2}, {3, 4}, ...
    'UniformOutput', false);
out.c = c;

% a very long string via concatenation of char vectors
longText = [ ...
    'The quick brown fox ' ...
    'jumps over the lazy dog ' ...
    'and then runs away ' ...
    'into the forest.'];
out.longText = longText;

% arithmetic chain with operators at the start of the continuation
x = 10 ...
  + 20 ...
  - 5 ...
  * 2;
out.x = x;

% nested calls, each on its own line
z = max( ...
        min( ...
            abs(vals) ...
        , 3) ...
    , 1);
out.z = z;

end
